$target=Join-Path $PSScriptRoot '..\server\src\hadith-admin.js'
$s=Get-Content -LiteralPath $target -Raw -Encoding utf8
$s=$s.Replace("const language=v=>{const x=clean(v,20).toLowerCase();return/^[a-z]{2,3}(?:-[a-z]{2,8})?$/.test(x)?x:'en'};", "const language=v=>{const x=clean(v,20).toLowerCase();return/^[a-z]{2,3}(?:-[a-z]{2,8})?$/.test(x)?x:'en'};`nconst editions={b:'bukhari',m:'muslim',a:'abudawud',t:'tirmidhi',s:'nasai',i:'ibnmajah',malik:'malik',q:'qudsi',n:'nawawi'},existingCache=new Map();")
$anchor=" router.post('/api/admin/hadith',admin"
$route=@'
 router.get('/api/admin/hadith/existing/:collectionId',admin,async(req,res)=>{try{const collectionId=clean(req.params.collectionId,20),edition=editions[collectionId];if(!edition)return res.status(400).json({message:'Unsupported Hadith collection.'});if(!existingCache.has(collectionId))existingCache.set(collectionId,Promise.all([fetch(`https://cdn.jsdelivr.net/gh/fawazahmed0/hadith-api@1/editions/eng-${edition}.min.json`).then(r=>{if(!r.ok)throw Error('English Hadith source unavailable.');return r.json()}),fetch(`https://cdn.jsdelivr.net/gh/fawazahmed0/hadith-api@1/editions/ara-${edition}.min.json`).then(r=>r.ok?r.json():null).catch(()=>null)]).then(([english,arabic])=>{const arabicMap=new Map((arabic?.hadiths||[]).map(x=>[String(x.hadithnumber),x.text]));return(english?.hadiths||[]).map(x=>({external:true,collectionId,collectionName:english?.metadata?.name||edition,book:String(x.reference?.book||'1'),sectionName:english?.metadata?.section?.[String(x.reference?.book||'1')]||`Book ${x.reference?.book||1}`,hadithNumber:String(x.hadithnumber),title:`Hadith ${x.hadithnumber}`,arabic:clean(arabicMap.get(String(x.hadithnumber)),20000),text:clean(x.text,30000),narrator:'',grade:(x.grades||[]).map(g=>g.grade).filter(Boolean).join(', '),explanation:'',reference:`${english?.metadata?.name||edition} ${x.hadithnumber}`,source:'fawazahmed0 Hadith API',published:true}))}));const all=await existingCache.get(collectionId),q=clean(req.query.q,200).toLowerCase(),filtered=q?all.filter(x=>(x.hadithNumber+' '+x.text+' '+x.sectionName).toLowerCase().includes(q)):all,page=Math.max(1,Number(req.query.page)||1),limit=Math.min(100,Math.max(10,Number(req.query.limit)||50)),start=(page-1)*limit;res.json({data:filtered.slice(start,start+limit),pagination:{page,limit,total:filtered.length,pages:Math.max(1,Math.ceil(filtered.length/limit))}})}catch(e){existingCache.delete(req.params.collectionId);console.error(e);res.status(502).json({message:'Existing app Hadith could not be loaded.'})}});
'@
if(-not $s.Contains("existing/:collectionId")){$s=$s.Replace($anchor,$route+$anchor)}
Set-Content -LiteralPath $target -Value $s -NoNewline -Encoding utf8
